// Normalizza i dati e prepara il prompt con la lista dei task attivi per deduplicazione semantica
const input = $('Execute Workflow Trigger').first().json;
const existingTasksRaw = $json.results || [];

const existingTasks = existingTasksRaw.map(t => ({
  id: t.id,
  task_name: t.properties['Task Name']?.title[0]?.plain_text || 'Senza nome',
  due_date: t.properties['Due Date']?.date?.start || null
}));

const meta = input.meta || {
  source: 'Manual',
  source_id: 'man_' + Date.now(),
  source_url: '',
  timestamp: new Date().toISOString()
};

const payload = input.payload || {
  title_hint: '',
  raw_content: String(input.text || input.content || JSON.stringify(input)),
  content_type: 'text',
  author_sender: 'Self'
};

const prompt = `Analizza il seguente contenuto per il Second Brain (metodologia CODE e framework PARA).

CONTENUTO DA ANALIZZARE:
"""
${payload.raw_content}
"""
METADATI:
- Fonte: ${meta.source}
- Autore: ${payload.author_sender || 'N/A'}
- Hint: ${payload.title_hint || 'Nessuno'}

TASK ATTUALMENTE APERTI SU NOTION (Verifica duplicati semantici):
${JSON.stringify(existingTasks, null, 2)}

REGOLE DEDUPLICAZIONE SEMANTICA:
Se il contenuto esprime un'azione/task, confrontalo con l'elenco dei TASK ATTUALMENTE APERTI.
Se l'azione proposta esprime la STESSA IDENTICA COSA o OBIETTIVO di un task già esistente (anche se formulata con sinonimi, perifrasi o parole diverse, ad esempio: "leggere capitolo 4" vs "leggere il capitolo dopo il 3"), imposta "is_duplicate": true e indica in "duplicate_of" il nome esatto del task esistente.
Se invece è un'azione nuova o diversa, imposta "is_duplicate": false.

RISPONDI ESCLUSIVAMENTE con un JSON con questa struttura esatta:
{
  "title": "Titolo chiaro e sintetico (max 8 parole)",
  "summary": "Sintesi distillata a bullet points",
  "para_category": "Project" | "Area" | "Resource" | "Task" | "None",
  "tasks": [
    {
      "task_name": "Verbo all'infinito + azione concreta",
      "due_date": "YYYY-MM-DD oppure null",
      "is_duplicate": true | false,
      "duplicate_of": "Nome esatto del task esistente se duplicato, altrimenti null"
    }
  ],
  "resource": {
    "is_resource": true | false,
    "type": "GitHub Repo" | "Article / Post" | "Paper" | "Tool / Lib" | "Snippet" | "Documentation",
    "tags": ["tag1", "tag2"]
  }
}`;

return {
  json: {
    meta,
    payload,
    prompt,
    existing_tasks_count: existingTasks.length
  }
};

// Estrae la risposta di Gemini e crea il body esatto per Notion Inbox
const geminiResponse = $json;
const prep = $('Prepare LLM Prompt with Deduplication').first().json;

let parsed = {};
try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: prep.payload.title_hint || 'Nota catturata',
    summary: prep.payload.raw_content.slice(0, 300),
    para_category: 'None',
    tasks: [],
    resource: { is_resource: false, type: 'Article / Post', tags: [] }
  };
}

// Costruzione payload esatto conforme allo schema reale di Notion Inbox
const notion_inbox_body = {
  parent: { database_id: $env.INBOX_DB_ID },
  properties: {
    'Name': {
      title: [{ text: { content: (parsed.title || prep.payload.title_hint || 'Nuova Nota').slice(0, 200) } }]
    },
    'Status': {
      status: { name: 'Inbox' }
    },
    'Source': {
      select: { name: ['Manual', 'Moodle', 'GitHub', 'Gmail', 'Outlook', 'Telegram Voice', 'Telegram Text'].includes(prep.meta.source) ? prep.meta.source : 'Manual' }
    },
    'Source ID': {
      rich_text: [{ text: { content: String(prep.meta.source_id || '') } }]
    },
    'PARA Routing': {
      select: { name: ['None', 'Task', 'Resource', 'Area', 'Project'].includes(parsed.para_category) ? parsed.para_category : 'None' }
    },
    'Raw Content': {
      rich_text: [{ text: { content: String(prep.payload.raw_content || '').slice(0, 1990) } }]
    },
    'AI Summary': {
      rich_text: [{ text: { content: String(parsed.summary || '').slice(0, 1990) } }]
    },
    'Captured At': {
      date: { start: prep.meta.timestamp ? prep.meta.timestamp.slice(0, 10) : new Date().toISOString().slice(0, 10) }
    }
  }
};

if (prep.meta.source_url) {
  notion_inbox_body.properties['Source URL'] = { url: prep.meta.source_url };
}

return {
  json: {
    meta: prep.meta,
    payload: prep.payload,
    distilled: parsed,
    notion_inbox_body
  }
};

// Estrae Tasks (filtrando i duplicati) e Resources
const inboxPageId = $json.id;
const parsed = $('Parse & Validate JSON').first().json;

const items = [];

if (parsed.distilled.tasks && Array.isArray(parsed.distilled.tasks)) {
  for (const t of parsed.distilled.tasks) {
    if (t.is_duplicate) {
      continue;
    }

    const taskSource = (parsed.meta.source && parsed.meta.source.startsWith('Telegram')) ? 'Telegram' : (['Manual', 'Moodle', 'GitHub', 'Gmail', 'Outlook'].includes(parsed.meta.source) ? parsed.meta.source : 'Manual');
    const taskBody = {
      parent: { database_id: $env.TASKS_DB_ID },
      properties: {
        'Task Name': {
          title: [{ text: { content: t.task_name.slice(0, 200) } }]
        },
        'Status': {
          status: { name: 'To Do' }
        },
        'Source': {
          select: { name: taskSource }
        },
        'Source Ref': {
          rich_text: [{ text: { content: String(parsed.meta.source_id || '') } }]
        }
      }
    };
    if (t.due_date && /^\d{4}-\d{2}-\d{2}/.test(t.due_date)) {
      taskBody.properties['Due Date'] = { date: { start: t.due_date } };
    }
    items.push({
      entity_type: 'task',
      body: taskBody
    });
  }
}

if (parsed.distilled.resource && parsed.distilled.resource.is_resource) {
  const resBody = {
    parent: { database_id: $env.RESOURCES_DB_ID },
    properties: {
      'Title': {
        title: [{ text: { content: parsed.distilled.title.slice(0, 200) } }]
      },
      'Type': {
        select: { name: parsed.distilled.resource.type || 'Article / Post' }
      },
      'Summary / Notes': {
        rich_text: [{ text: { content: String(parsed.distilled.summary || '').slice(0, 1990) } }]
      }
    }
  };
  if (parsed.meta.source_url) {
    resBody.properties['URL'] = { url: parsed.meta.source_url };
  }
  if (parsed.distilled.resource.tags && Array.isArray(parsed.distilled.resource.tags)) {
    resBody.properties['Tags'] = {
      multi_select: parsed.distilled.resource.tags.map(tag => ({ name: String(tag) }))
    };
  }
  items.push({
    entity_type: 'resource',
    body: resBody
  });
}

if (items.length === 0) {
  return [{ json: { status: 'no_child_entities', inbox_id: inboxPageId } }];
}

return items.map(i => ({ json: i }));

// Genera il feedback dettagliato per Telegram distinguendo nuovi task e duplicati evitati
const parsed = $('Parse & Validate JSON').first().json;
const inboxPage = $('Notion - Save to Inbox').first().json;

const newTasks = [];
const duplicates = [];

if (parsed.distilled.tasks && Array.isArray(parsed.distilled.tasks)) {
  for (const t of parsed.distilled.tasks) {
    if (t.is_duplicate) {
      duplicates.push(t);
    } else {
      newTasks.push(t);
    }
  }
}

let feedback = `🧠 *Second Brain Aggiornato!*\n\n📌 *Nota:* ${parsed.distilled.title}`;

if (newTasks.length > 0) {
  feedback += `\n\n✅ *Nuovo Task aggiunto:*\n` + newTasks.map(t => `• ${t.task_name}${t.due_date ? ` (📅 ${t.due_date})` : ''}`).join('\n');
}

if (duplicates.length > 0) {
  feedback += `\n\n⚠️ *Task già presente (duplicato evitato):*\n` + duplicates.map(d => `• L'azione corrisponde a: *"${d.duplicate_of || d.task_name}"*`).join('\n');
}

if (parsed.distilled.resource && parsed.distilled.resource.is_resource) {
  feedback += `\n\n📚 *Risorsa aggiunta:* ${parsed.distilled.title}`;
}

return {
  json: {
    status: 'success',
    inbox_id: inboxPage.id,
    title: parsed.distilled.title,
    new_tasks_count: newTasks.length,
    duplicates_count: duplicates.length,
    feedback_message: feedback
  }
};
